// Simula el Gmail Trigger: devuelve dos mails, como si hubieran llegado juntos.
// Cada uno es un "item": el resto del flujo corre una vez por cada uno.
return [
  { json: { de: 'Martín Gómez', text: "hola!! como andan? les escribo xq queremos ir con mi señora y los 2 chicos a bariloche en las\nvacaciones de invierno, la idea seria salir el 14 de julio mas o menos y volver una semana despues.\nsomos de rosario. presupuesto no se, unos 2 millones?? si tienen algo con hotel y excursiones mejor.\nah y uno de los nenes es celiaco. me llamo Martín Gómez, mi cel 341 555-0192. gracias!!!" } },
  { json: { de: 'Lucía Fernández', text: "Buenas tardes. Consulto por un paquete a Cancún para 2 adultos, del 3 al 10 de marzo de 2027.\nSalimos desde Córdoba. Nos interesa all inclusive. Mi correo es lucia.fernandez@mail.com.\nSaludos, Lucía Fernández." } },
];

// La IA devuelve el JSON como texto. Acá lo convertimos en una ficha con casilleros.
// Si la IA agregó ``` o algún texto alrededor, se lo sacamos.
const texto = $json.text || '';
const inicio = texto.indexOf('{');
const fin = texto.lastIndexOf('}');
return { json: JSON.parse(texto.slice(inicio, fin + 1)) };
